import torch.nn as nn

class RepresentationNet(nn.Module):
    def __init__(self, in_dim, rep_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, 128), nn.ReLU(),
            nn.Linear(128, 64), nn.ReLU(),
            nn.Linear(64, rep_dim),
        )
    def forward(self, X):
        return self.net(X)
